; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if4_e_go:			ld sp, if4_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld de, var_chk_got		; (the block of 2 parameters)
			ldi
			ldi
			pop hl			; want
			ldi
			ldi
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_rep_c:		; call rep (normal)
			pop hl			; c
			ld de, var_rep_c
			ld b, 255
p_rep_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_rep_si0_e
			inc hl
			inc de
			djnz p_rep_si0
			xor a
			ld (de), a
p_rep_si0_e:
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_rep_n), de
			xor a
			ld (var_rep_rep), a
			ld (p_rep_rs), sp
			ld sp, p_rep
			jp ntc_xn
p_rep_r:		; end of rep
			ld sp, (p_rep_rs)
			jp ntc_xn
p_lenof_c:		; call lenof (normal)
			pop hl			; x
			ld de, var_lenof_x
			ld b, 255
p_lenof_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_lenof_si0_e
			inc hl
			inc de
			djnz p_lenof_si0
			xor a
			ld (de), a
p_lenof_si0_e:
			ld hl, 0
			ld (var_lenof_lenof), hl
			ld (p_lenof_rs), sp
			ld sp, p_lenof
			jp ntc_xn
p_lenof_r:		; end of lenof
			ld sp, (p_lenof_rs)
			jp ntc_xn
p_fill_c:		; call fill (normal)
			pop hl			; x
			ld (p_fill_a0), hl
			ld de, var_fill_x
			ld b, 255
p_fill_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_fill_si0_e
			inc hl
			inc de
			djnz p_fill_si0
			xor a
			ld (de), a
p_fill_si0_e:
			ld (p_fill_rs), sp
			ld sp, p_fill
			jp ntc_xn
p_fill_r:		; end of fill
			ld de, (p_fill_a0)
			ld hl, var_fill_x
			dec de
			ld a, (de)		; the destination's capacity
			ld b, a
			inc de
p_fill_so0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_fill_so0_e
			inc hl
			inc de
			djnz p_fill_so0
			xor a
			ld (de), a
p_fill_so0_e:
			ld sp, (p_fill_rs)
			jp ntc_xn
p_setel_c:		; call setel (normal)
			pop hl			; a() descriptor
			ld de, pa_setel_a
			ld bc, 12
			ldir
			ld (p_setel_rs), sp
			ld sp, p_setel
			jp ntc_xn
p_setel_r:		; end of setel
			ld sp, (p_setel_rs)
			jp ntc_xn

